import { Directive, effect, inject, InjectionToken, input } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import { ButtonStyle } from './style/buttonstyle';

export const BUTTON_ICON_INSTANCE = new InjectionToken<ButtonIcon>('BUTTON_ICON_INSTANCE');

/**
 * ButtonIcon is a directive to apply icon styling to an element inside a button.
 *
 * @deprecated Since v21. Place the icon (`<svg>`, `<i>`, or any element) directly
 * inside the `[pButton]` host — use the `iconOnly` prop to enable icon-only styling.
 * The `pButtonIcon` directive will be removed in a future major release.
 *
 * @group Directives
 */
@Directive({
    selector: '[pButtonIcon]',
    providers: [ButtonStyle, { provide: BUTTON_ICON_INSTANCE, useExisting: ButtonIcon }, { provide: PARENT_INSTANCE, useExisting: ButtonIcon }],
    standalone: true,
    host: {
        '[class.p-button-icon]': '!$unstyled() && true'
    },
    hostDirectives: [Bind]
})
export class ButtonIcon extends BaseComponent {
    componentName = 'ButtonIcon';

    /**
     * Used to pass attributes to DOM elements inside the pButtonIcon.
     * @defaultValue undefined
     * @group Props
     */
    pButtonIconPT = input<any>();
    /**
     * Indicates whether the component should be rendered without styles.
     * @defaultValue undefined
     * @group Props
     */
    pButtonUnstyled = input<boolean | undefined>();

    $pcButtonIcon: ButtonIcon | undefined = inject(BUTTON_ICON_INSTANCE, { optional: true, skipSelf: true }) ?? undefined;

    bindDirectiveInstance = inject(Bind, { self: true });

    constructor() {
        super();
        effect(() => {
            const pt = this.pButtonIconPT();

            if (pt) {
                this.directivePT.set(pt);
            }
        });

        effect(() => {
            if (this.pButtonUnstyled()) {
                this.directiveUnstyled.set(this.pButtonUnstyled());
            }
        });
    }

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptms(['host', 'root']));
    }
}
