import { booleanAttribute, computed, contentChild, Directive, effect, inject, InjectionToken, input, NgModule } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import { Fluid } from 'primeng/fluid';
import { Ripple } from 'primeng/ripple';
import type { ButtonDirectiveOptions, ButtonPassThrough, ButtonSeverity, ButtonSize, ButtonVariant } from 'primeng/types/button';
import { ButtonStyle } from './style/buttonstyle';
import { Button } from './button.component';
import { ButtonIcon } from './button-icon';
import { ButtonLabel } from './button-label';

export { Button, BUTTON_INSTANCE } from './button.component';
export { ButtonIcon, BUTTON_ICON_INSTANCE } from './button-icon';
export { ButtonLabel, BUTTON_LABEL_INSTANCE } from './button-label';

const BUTTON_DIRECTIVE_INSTANCE = new InjectionToken<ButtonDirective>('BUTTON_DIRECTIVE_INSTANCE');

/**
 * Button directive is an extension to button component.
 * @group Directives
 */
@Directive({
    selector: '[pButton]',
    standalone: true,
    providers: [ButtonStyle, { provide: BUTTON_DIRECTIVE_INSTANCE, useExisting: ButtonDirective }, { provide: PARENT_INSTANCE, useExisting: ButtonDirective }],
    host: {
        '[class]': 'styleClass()',
        '[style]': 'hostStyle()'
    },
    hostDirectives: [Bind, Ripple]
})
export class ButtonDirective extends BaseComponent {
    componentName = 'Button';

    /**
     * Bound configuration object. Fields win over the individual styling inputs
     * (`text`, `raised`, `severity`, …); unset fields fall back to those inputs.
     * @group Props
     */
    pButton = input<ButtonDirectiveOptions | string | undefined>(undefined);

    /**
     * Used to pass attributes to DOM elements inside the Button component.
     * @group Props
     */
    pButtonPT = input<ButtonPassThrough>();

    /**
     * Indicates whether the component should be rendered without styles.
     * @group Props
     */
    pButtonUnstyled = input<boolean | undefined>();

    /**
     * @group Props
     */
    hostName = input<any>('');

    /**
     * Add a textual class to the button without a background initially.
     * @group Props
     */
    text = input(false, { transform: booleanAttribute });

    /**
     * Add a plain textual class to the button without a background initially.
     * @group Props
     */
    plain = input(false, { transform: booleanAttribute });

    /**
     * Add a shadow to indicate elevation.
     * @group Props
     */
    raised = input(false, { transform: booleanAttribute });

    /**
     * Defines the size of the button.
     * @group Props
     */
    size = input<ButtonSize>();

    /**
     * Add a border class without a background initially.
     * @group Props
     */
    outlined = input(false, { transform: booleanAttribute });

    /**
     * Renders the button as a textual link without background or border.
     * @group Props
     */
    link = input(false, { transform: booleanAttribute });

    /**
     * Add a circular border radius to the button.
     * @group Props
     */
    rounded = input(false, { transform: booleanAttribute });

    /**
     * Spans 100% width of the container when enabled.
     * @group Props
     */
    fluid = input(undefined, { transform: booleanAttribute });

    /**
     * Visual variant of the button. Equivalent to setting `text` or `outlined` individually.
     * @group Props
     */
    variant = input<ButtonVariant>();

    /**
     * Forces icon-only styling regardless of content. Works with any direct icon child
     * (`<svg>`, `<i>`, custom).
     * @group Props
     */
    iconOnly = input(false, { transform: booleanAttribute });

    /**
     * Whether the button is in loading state.
     * @deprecated Manage loading state with native `disabled` and a child spinner; this input will be removed in a future release.
     * @group Props
     */
    loading = input(false, { transform: booleanAttribute });

    /**
     * Defines the style of the button.
     * @group Props
     */
    severity = input<ButtonSeverity>();

    $pcButtonDirective: ButtonDirective | undefined = inject(BUTTON_DIRECTIVE_INSTANCE, { optional: true, skipSelf: true }) ?? undefined;

    bindDirectiveInstance = inject(Bind, { self: true });

    pcFluid: Fluid | null = inject(Fluid, { optional: true, host: true, skipSelf: true });

    _componentStyle = inject(ButtonStyle);

    private iconSignal = contentChild(ButtonIcon, { descendants: false });

    private labelSignal = contentChild(ButtonLabel, { descendants: false });

    /** @deprecated Use the `iconOnly` input instead. */
    isIconOnly = computed(() => !!(!this.labelSignal() && this.iconSignal()));

    styleClass = computed(() => {
        if (this.$unstyled()) return '';

        const v = this.pButton();
        const o: ButtonDirectiveOptions = typeof v === 'object' && v !== null ? v : {};
        const stringSeverity = typeof v === 'string' && v !== '' ? (v as ButtonSeverity) : undefined;
        const severity = o.severity ?? stringSeverity ?? this.severity();
        const size = o.size ?? this.size();
        const variant = o.variant ?? this.variant();

        const base = this.cn('p-button', 'p-component', {
            'p-button-icon-only': this.iconOnly() || o.iconOnly || this.isIconOnly(),
            'p-button-loading': this.loading(),
            'p-disabled': this.loading(),
            'p-button-text': this.text() || variant === 'text' || o.text,
            'p-button-outlined': this.outlined() || variant === 'outlined' || o.outlined,
            'p-button-link': this.link() || variant === 'link' || o.link,
            'p-button-plain': this.plain() || o.plain,
            'p-button-raised': this.raised() || o.raised,
            'p-button-rounded': this.rounded() || o.rounded,
            'p-button-sm': size === 'small',
            'p-button-lg': size === 'large',
            'p-button-fluid': this.fluid() ?? o.fluid ?? !!this.pcFluid,
            [`p-button-${severity}`]: !!severity
        });

        return o.styleClass ? `${base} ${o.styleClass}` : base;
    });

    hostStyle = computed(() => {
        const v = this.pButton();
        const o: ButtonDirectiveOptions = typeof v === 'object' && v !== null ? v : {};

        return o.style ?? null;
    });

    constructor() {
        super();

        effect(() => {
            const pt = this.pButtonPT();

            if (pt) this.directivePT.set(pt);
        });
        effect(() => {
            const unstyled = this.pButtonUnstyled();

            if (unstyled !== undefined) this.directiveUnstyled.set(unstyled);
        });
    }

    onAfterViewChecked(): void {
        this.bindDirectiveInstance.setAttrs(this.ptm('root'));
    }
}

@NgModule({
    imports: [ButtonDirective, Button, ButtonLabel, ButtonIcon],
    exports: [ButtonDirective, Button, ButtonLabel, ButtonIcon]
})
export class ButtonModule {}
